mapper.select:
SELECT tran_no
FROM (
  SELECT t.tran_no
  FROM transaction t
  WHERE t.buyer_id = #{buyerId}
    AND t.prod_no  = #{prodNo}
  ORDER BY t.tran_no DESC
)
WHERE ROWNUM = 1

mapper.update:
UPDATE transaction
   SET tran_status_code = #{tranCode, jdbcType=CHAR}
 WHERE tran_no = #{tranNo}

UPDATE transaction
   SET tran_status_code = #{tranCode, jdbcType=CHAR}
 WHERE prod_no = #{prodNo}

mapper.select:
SELECT COUNT(1)
  FROM transaction
 WHERE buyer_id = #{buyerId}
   AND prod_no  = #{prodNo}
